message.content:
{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is spread under a flickering streetlamp at the city's edge.",
      "visual_description": "Mara unrolls a hand-drawn map on a cracked cobblestone outside the ruined royal city; broken spires rise in the distance under a bruised sky.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp warns of three temptations before dawn.",
      "visual_guidance": "ignored",
      "visual_description": "Close-up of Oracle Lamp's single glowing eye in its flame, casting warning shadows across Mara's tired face and ink-stained coat.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The clockwork scout is wound and sent ahead.",
      "visual_description": "Mara turns a brass key in Tin Fox's tail; the little metal fox's blue glass eyes blink on as it darts down a rubble-strewn lane.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The castle gates loom, gilded and obviously trapped.",
      "visual_description": "Towering golden gates carved with roaring beasts; Tin Fox crouches in the shadow of a fallen banner, ears swiveling.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Glass Diver arrives by stepping out of a shop window.",
      "visual_description": "A tall figure in a clear diving helmet emerges from a cracked storefront pane, coat shimmering with broken neon reflections of the dead city.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower whispers promises of treasure.",
      "visual_description": "A leaning black tower wreathed in green mist; Oracle Lamp tugs against Mara's grip, its eye narrowed in disapproval.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "They skirt the tower and find a slumped official at a checkpoint.",
      "visual_description": "Sleeping Tax Collector snores at a tipped-over toll desk, ledger book under his cheek, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara stamps her own pass and walks them through.",
      "visual_description": "Mara presses the official's seal onto a blank parchment while Sleeping Tax Collector mutters in his sleep; Glass Diver tips a helmet in mock salute.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox returns with a torn royal banner clutched in its jaws.",
      "visual_description": "The clockwork fox drops a faded crimson banner at Mara's feet; embroidered crowns are scorched and fraying.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Rumor of a great winged beast echoes down an empty avenue.",
      "visual_description": "An enormous clawed shadow ripples across rooftops above the party; Glass Diver stares up, helmet catching the silhouette in distorted reflection.",
      "characters": ["glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Oracle Lamp insists the shadow is only painted on smoke.",
      "visual_description": "The lamp's flame stretches tall, eye scolding; behind it the 'beast' dissolves into drifting colored vapor over the ruined plaza.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "An armored patrol clanks past in lockstep.",
      "visual_description": "From a flooded alley, Mara and Glass Diver crouch behind a toppled fountain as polished black armor marches by, lance-tips dragging sparks.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver dives into a rain puddle and surfaces inside the keep.",
      "visual_description": "Split panel feel: Glass Diver plunges into a shallow puddle outside; coat-tails vanish, then emerge from a tall mirror in a vaulted marble hall.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door demands a true name to open.",
      "visual_description": "A door of swirling silver runes pulses in a dim corridor; Oracle Lamp hovers close, whispering letters that float up like sparks.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, the captive is found chained to a mirrored throne.",
      "visual_description": "A frightened figure — actually Sleeping Tax Collector's twin, ledger and all — slumped in silver chains; Glass Diver kneels to pick the lock.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox chews through a bell-wire to delay the alarm.",
      "visual_description": "The clockwork fox bites a humming brass wire on a stairwell; sparks fly across its blue glass eyes as distant bells choke into silence.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The party regroups at the foot of the long stone bridge.",
      "visual_description": "Mara, Glass Diver carrying the drowsy official, Tin Fox at their heels, and Oracle Lamp held high before a moonlit arched bridge over a black river.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge as the ruined city collapses behind them.",
      "visual_description": "Wide shot: the five silhouettes hurry across the bridge while towers crumble in slow plumes of dust; Oracle Lamp's eye glows like a small second moon.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    }
  ]
}

